import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const silencePhysicalScenarios=['silence-physical-resist','silence-physical-recover','silence-physical-cancel'] as const;
export type SilencePhysicalScenario=typeof silencePhysicalScenarios[number];
export function isSilencePhysicalScenario(name:string):name is SilencePhysicalScenario{return (silencePhysicalScenarios as readonly string[]).includes(name);}
export function makeSilencePhysicalScenario(name:SilencePhysicalScenario,players:{id:string;name:string}[],options:{level?:number;spirit?:number;kit?:'forms'|'heal'|'virtual';guardian?:boolean;cult?:boolean}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,['白魔術師シェリム',options.cult?'邪祭ウーノス':'凍気のアイエル','大神官ジル','侍大将のシン'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+6-gameStats(s,p.id).spirit;}s.players[a]!.permanent!.magic_level=20+(options.level??6)-gameStats(s,a).magic_level;s.players[b]!.permanent!.spirit!+= (options.spirit??(name==='silence-physical-resist'?14:13))-gameStats(s,b).spirit;
 const front=options.kit?null:takeCard(s,b,options.guardian?'守護者':'メタルゴーレム'),rear=options.kit||options.guardian?null:takeCard(s,b,options.cult?'竜王教団':'水竜'),keep=[takeCard(s,a,'a2-p18-r1c1'),takeCard(s,a,'a2-p15-r3c2'),takeCard(s,a,'必勝の祈り'),takeCard(s,b,'a2-p14-r2c3'),takeCard(s,b,'a2-p12-r2c2'),takeCard(s,b,'a2-p12-r3c2'),takeCard(s,d,'命運凶変'),...[front,rear].filter((x):x is string=>!!x)];if(options.kit==='forms')keep.push(takeCard(s,b,'a2-p14-r2c1'),takeCard(s,b,'a2-p07-r3c3'));if(options.kit==='virtual')keep.push(takeCard(s,b,'a2-p24-r1c2'));if(options.kit==='heal')keep.push(takeCard(s,b,'回復の薬'));for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`SILENCE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('SILENCE_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('SILENCE_IDS');}
 for(const p of players){for(const cardInstanceId of (p.id===b?[front,rear]:[]).filter((x):x is string=>!!x))act(p.id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(p.id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
